+        private async Task<List<ReceiptForOrder>> GetReceiptHistory(int orderId)
+        {
+            var receiptList = new List<ReceiptForOrder>();
+
+            // 1. 查询本订单关联的所有发票（通过 DLN1 → INV1 链路）
+            var dln1DocEntries = await UnitWork.Find<DLN1>(de => de.BaseEntry == orderId && de.BaseType == 17)
+                .Select(de => de.DocEntry)
+                .ToListAsync();
+
+            var orderInv1Entries = new List<int>();
+            if (dln1DocEntries.Any())
+            {
+                orderInv1Entries = await UnitWork.Find<INV1>(ie =>
+                    dln1DocEntries.Contains(ie.BaseEntry) && ie.BaseType == 15)
+                    .Select(ie => ie.DocEntry.Value)
+                    .ToListAsync();
+            }
+
+            // 2. 查询直接收款（U_XSDD = orderId）
+            var directReceipts = await UnitWork.Find<ORCT>(r => r.U_XSDD == orderId && r.Canceled != "Y")
+                .ToListAsync();
+
+            // 3. 查询本订单发票的 RCT2 核销记录（含 SumApplied）
+            var rct2Data = new List<(int DocNum, int InvDocEntry, decimal SumApplied, decimal AppliedFC)>();
+            if (orderInv1Entries.Any())
+            {
+                var rct2List = await UnitWork.Find<RCT2>(re =>
+                    orderInv1Entries.Contains(re.DocEntry.Value) && re.InvType == "13")
+                    .Select(re => new { re.DocNum, DocEntry = re.DocEntry, re.SumApplied, re.AppliedFC })
+                    .ToListAsync();
+                rct2Data = rct2List
+                    .Where(re => re.DocEntry.HasValue)
+                    .Select(re => (re.DocNum, re.DocEntry.Value, re.SumApplied ?? 0M, re.AppliedFC ?? 0M))
+                    .ToList();
+            }
+
+            // 4. 查询间接收款（通过 RCT2 关联，排除直接收款）
+            var directDocNums = directReceipts.Select(r => r.DocNum).ToHashSet();
+            var indirectDocNums = rct2Data.Select(r => r.DocNum).Where(n => !directDocNums.Contains(n)).Distinct().ToList();
+            var indirectReceipts = indirectDocNums.Any()
+                ? await UnitWork.Find<ORCT>(r => indirectDocNums.Contains(r.DocNum) && r.Canceled != "Y" && !r.U_XSDD.HasValue).ToListAsync()
+                : new List<ORCT>();
+
+            // 5. 处理直接收款（U_XSDD有值）：直接使用 ORCT.DocTotal 作为该订单的收款金额
+            // 原因：部分收款走日记帐科目而非发票核销，RCT2.SumApplied 无法反映完整金额
+            foreach (var receipt in directReceipts)
+            {
+                receiptList.Add(new ReceiptForOrder
+                {
+                    DocEntry = receipt.DocEntry,
+                    DocNum = receipt.DocNum,
+                    DocDate = receipt.DocDate,
+                    Canceled = receipt.Canceled,
+                    AppliedAmount = receipt.DocTotal ?? 0M,
+                    AppliedAmountFC = receipt.DocTotalFC ?? 0M
+                });
+            }
+
+            // 6. 处理间接收款（使用 RCT2.SumApplied 聚合）
+            foreach (var receipt in indirectReceipts)
+            {
+                var matchingRct2 = rct2Data.Where(r => r.DocNum == receipt.DocNum && orderInv1Entries.Contains(r.InvDocEntry)).ToList();
+                var appliedAmount = matchingRct2.Sum(r => r.SumApplied);
+                var appliedAmountFC = matchingRct2.Sum(r => r.AppliedFC);
+                if (appliedAmount > 0 || appliedAmountFC > 0)
+                {
+                    receiptList.Add(new ReceiptForOrder
+                    {
+                        DocEntry = receipt.DocEntry,
+                        DocNum = receipt.DocNum,
+                        DocDate = receipt.DocDate,
+                        Canceled = receipt.Canceled,
+                        AppliedAmount = appliedAmount,
+                        AppliedAmountFC = appliedAmountFC
+                    });
+                }
+            }
+
+            return receiptList
+                .GroupBy(r => r.DocEntry)
+                .Select(g => new ReceiptForOrder
+                {
+                    DocEntry = g.Key,
+                    DocNum = g.First().DocNum,
+                    DocDate = g.First().DocDate,
+                    Canceled = g.First().Canceled,
+                    AppliedAmount = g.Sum(r => r.AppliedAmount),
+                    AppliedAmountFC = g.Sum(r => r.AppliedAmountFC)
+                })
+                .OrderBy(r => r.DocDate)
+                .ToList();
+        }
