+                    var eventEndDate = pe.ResolvedDate ?? endDate;
+                    var actualStartDate = eventStartDate > startDate ? eventStartDate : startDate;
+                    var actualEndDate = eventEndDate < endDate ? eventEndDate : endDate;
+                    var currentEventLedgers = penaltyLedgers.Where(pl => pl.EventId == pe.Id).ToList();
+                    var currentEventLedgersDateHashSet = currentEventLedgers.Select(pl => pl.TransactionDate).ToHashSet();
+                    if (actualStartDate > actualEndDate) continue;
+
+                    var dailyOverdueDetails = await _historicalAfterBillOverdueCalculationService.CalculateDailyOverdueDetails(order.DocEntry, actualStartDate, actualEndDate, isSchoolOrResearch);
+
+                    var saleOrderPlugin = await UnitWork.Find<SaleOrderPlugin>(sp => sp.DocEntry == order.DocEntry).FirstOrDefaultAsync();
+                    decimal factor = (saleOrderPlugin?.NeedReturn == NeedReturnEnums.Select) ? 0.5M : 1.0M;
+
+                    var rule = await GetApplicablePenaltyRule(isSchoolOrResearch);
+                    if (rule == null) continue;
+                    var rateTiers = Newtonsoft.Json.JsonConvert.DeserializeObject<List<InterestRateTier>>(rule.Param_String1);
+                    var addLedgers = new List<PenaltyLedger>(); 
+                    foreach (var dailyDetail in dailyOverdueDetails.Where(d => !d.IsInGracePeriod && d.OverdueAmount > 0 && !currentEventLedgersDateHashSet.Contains(d.CalculationDate)))
+                    {
+                        var (dailyPenalty, rate) =  CalculateDailyPenalty( dailyDetail, factor, rateTiers);
+                        if (dailyPenalty > 0) 
+                        {
+                            var ledger = await CreatePenaltyLedgerEntry(order, pe, dailyDetail, dailyPenalty, rate, dailyDetail.CalculationDate, slpNames);
+                            addLedgers.Add(ledger);
+                        }
+                        
+                    }
+                    await UnitWork.BatchAddAsync<PenaltyLedger,int>(addLedgers.ToArray());
+                    await UnitWork.SaveAsync();
+                }
+            }
+            catch (Exception ex)
+            {
+                LogHelper.Error(ex, $"处理订单{order.DocEntry}的开票后历史逾期数据失败", nameof(HistoricalAfterBillOverdueImportService), nameof(ProcessSingleOrderByRange));
+            }
+        }
+
+        private static (decimal PenaltyAmount, decimal Rate) CalculateDailyPenalty(HistoricalAfterBillOverdueCalculationService.DailyOverdueDetail dailyDetail, decimal factor, List<InterestRateTier> rateTiers)
+        {
+            var matchedTier = rateTiers.FirstOrDefault(tier => (tier.Min == null || dailyDetail.OverdueDays >= tier.Min) && (tier.Max == null || dailyDetail.OverdueDays <= tier.Max));
+            if (matchedTier == null) return (0, 0);
+            return (dailyDetail.OverdueAmount * (matchedTier.Rate / 100M /365M) * factor, matchedTier.Rate / 100M /365M);
+        }
