+        private async Task ProcessOverduePeriodWithEventTracking(ORDR order, DateTime? calculationDate = null)
+        {
+            var customerTypes = await _customerCommonApp.GetMainlandCustomerType();
+            var customerType = customerTypes.FirstOrDefault(ct => ct.CardCode == order.CardCode);
+            bool isSchoolOrResearch = customerType != null && (customerType.CardType.Contains("校") || customerType.CardType.Contains("研"));
+            int gracePeriod = isSchoolOrResearch ? 365 : 180;
+
+            var rule = await GetApplicablePenaltyRule(isSchoolOrResearch);
+            if (rule == null) return;
+
+            var events = await GetAllEvents(order.DocEntry);
+            var allInvoices = events.Where(e => e.EventType == "Invoice").OrderBy(e => e.EventDate).ToList();
+
+            for (int i = 0; i < events.Count; i++)
+            {
+                var @event = events[i];
+                var currentOverdueInfo = await _historicalAfterBillOverdueCalculationService.CalculateHistoricalAfterBillOverdue(order.DocEntry, @event.EventDate);
+                await SyncPenaltyEventState(order, @event.EventDate, currentOverdueInfo, gracePeriod, rule.Id);
+
+                DateTime nextDate = (i < events.Count - 1) ? events[i + 1].EventDate : (calculationDate ?? @event.EventDate);
+                if (nextDate <= @event.EventDate) continue;
+
+                // Look Ahead Logic
+                var totalReceipts = events.Where(e => e.EventType == "Receipt" && e.EventDate <= @event.EventDate).Sum(e => e.Amount);
+                decimal remainingReceipts = totalReceipts;
+                DateTime? firstUnpaidInvoiceDate = null;
+
+                foreach (var inv in allInvoices)
+                {
+                    if (inv.EventDate > @event.EventDate) break;
+                    if (remainingReceipts >= inv.Amount) remainingReceipts -= inv.Amount;
+                    else { firstUnpaidInvoiceDate = inv.EventDate; break; }
+                }
+
+                if (firstUnpaidInvoiceDate.HasValue)
+                {
+                    var overdueStartDate = firstUnpaidInvoiceDate.Value.AddDays(gracePeriod + 1);
+                    if (overdueStartDate > @event.EventDate && overdueStartDate < nextDate)
+                    {
+                        var midStatus = await _historicalAfterBillOverdueCalculationService.CalculateHistoricalAfterBillOverdue(order.DocEntry, overdueStartDate);
+                        await SyncPenaltyEventState(order, overdueStartDate, midStatus, gracePeriod, rule.Id);
+                    }
+                }
+            }
+
+            if (events.Any() && calculationDate.HasValue && calculationDate.Value > events[events.Count-1].EventDate)
+            {
+                var finalInfo = await _historicalAfterBillOverdueCalculationService.CalculateHistoricalAfterBillOverdue(order.DocEntry, calculationDate.Value);
+                await SyncPenaltyEventState(order, calculationDate.Value, finalInfo, gracePeriod, rule.Id);
+            }
+        }
+
+        private async Task SyncPenaltyEventState(ORDR order, DateTime date, HistoricalAfterBillOverdueCalculationService.AfterBillOverdueAmountAndDays info, int gracePeriod, int ruleId)
+        {
+            var activeEvent = await GetActivePenaltyEvent(order.DocEntry);
+            bool isOverdue = info.TotalOverdueAmount > 0 && info.TotalOverdueDays > gracePeriod;
+
+            if (isOverdue)
+            {
+                if (activeEvent == null) await CreateNewPenaltyEvent(order, date, info, ruleId);
+                else if (Math.Abs(activeEvent.PenaltyBaseAmount - info.TotalOverdueAmount) > 0.01M)
+                {
+                    await EndCurrentEvent(activeEvent, date);
+                    await CreateNewPenaltyEvent(order, date, info, ruleId);
+                }
+            }
+            else if (activeEvent != null) await EndCurrentEvent(activeEvent, date);
+        }
