+        private async Task<List<OrderEvent>> GetAllEvents(int orderId)
+        {
+            var events = new List<OrderEvent>();
+            var invoices = await GetInvoiceHistory(orderId);
+            foreach (var inv in invoices) events.Add(new OrderEvent { EventDate = inv.InvoiceDate, EventType = "Invoice", Amount = inv.InvoiceAmount });
+            var receipts = await GetReceiptHistory(orderId);
+            foreach (var rct in receipts) events.Add(new OrderEvent { EventDate = rct.DocDate.Value, EventType = "Receipt", Amount = rct.AppliedAmount });
+            return events.OrderBy(x => x.EventDate).ToList();
