+        /// <summary>
+        /// 重新计算历史开票逾期罚息（并行版本）
+        /// </summary>
+        /// <param name="startDate">开始日期</param>
+        /// <param name="endDate">结束日期</param>
+        /// <param name="ruleDefinitionIds">规则定义ID列表（默认9和10）</param>
+        /// <param name="maxDegreeOfParallelism">最大并行度（默认4）</param>
+        /// <returns>重算结果统计</returns>
+        public async Task<RecalculationResult> RecalculateHistoricalAfterBillOverdueParallel(
+            DateTime startDate,
+            DateTime endDate,
+            List<int> ruleDefinitionIds = null,
+            int maxDegreeOfParallelism = 4)
+        {
+            ruleDefinitionIds = ruleDefinitionIds ?? new List<int> { 9, 10 };
+            var result = new RecalculationResult
+            {
+                StartTime = DateTime.Now,
+                RuleDefinitionIds = ruleDefinitionIds
+            };
+
+            try
+            {
+                LogHelper.Info($"开始重新计算{startDate:yyyy-MM-dd}至{endDate:yyyy-MM-dd}的开票后历史逾期罚息（规则：{string.Join(",", ruleDefinitionIds)}）",
+                    nameof(HistoricalAfterBillOverdueImportService), nameof(RecalculateHistoricalAfterBillOverdueParallel));
+
+                // 1. 查询需要重新计算的订单（所有有开票后罚息事件的订单）
+                var orders = await GetCompletedOrdersWithHistoricalAfterBillOverdue();       
+                result.TotalOrders = orders.Count;
+
+                LogHelper.Info($"共找到 {result.TotalOrders} 个订单需要重新计算",
+                    nameof(HistoricalAfterBillOverdueImportService), nameof(RecalculateHistoricalAfterBillOverdueParallel));
+
+                if (!orders.Any())
+                {
+                    LogHelper.Info("没有订单需要重新计算",
+                        nameof(HistoricalAfterBillOverdueImportService), nameof(RecalculateHistoricalAfterBillOverdueParallel));
+                    result.EndTime = DateTime.Now;
+                    return result;
+                }
+
+                // 2. 查询所有订单信息
+                result.TotalOrders = orders.Count;
+
+                LogHelper.Info($"实际有效订单数：{result.TotalOrders}",
+                    nameof(HistoricalAfterBillOverdueImportService), nameof(RecalculateHistoricalAfterBillOverdueParallel));
+
+                // 3. 批量预加载共享数据
+                var sharedData = await PreloadSharedData(orders);
+                LogHelper.Info("预加载共享数据完成",
+                    nameof(HistoricalAfterBillOverdueImportService), nameof(RecalculateHistoricalAfterBillOverdueParallel));
+
+                // 4. 使用并行处理每个订单
+                var lockObj = new object();
+                var stopwatch = Stopwatch.StartNew();
+                var progressLogIntervalSeconds = 10; // 每10秒记录一次进度
+                DateTime lastProgressLogTime = DateTime.MinValue;
+
+                var parallelOptions = new ParallelOptions
+                {
+                    MaxDegreeOfParallelism = maxDegreeOfParallelism
+                };
+
+                await Task.Run(() =>
+                {
+                    Parallel.ForEach(
+                        orders,
+                        parallelOptions,
+                        (order, state) =>
+                        {
+                            using (var scope = _serviceProvider.CreateScope())
+                            {
+                                try
+                                {
+                                    var scopedUnitWork = scope.ServiceProvider.GetRequiredService<IUnitWork>();
+                                    var scopedCalculationService = scope.ServiceProvider.GetRequiredService<HistoricalAfterBillOverdueCalculationService>();
+
+                                    // 执行单订单重新计算
+                                    RecalculateSingleOrderInternal(
