+        private async Task SyncPenaltyEventState(ORDR order, DateTime date, HistoricalAfterBillOverdueCalculationService.AfterBillOverdueAmountAndDays info, int gracePeriod, int ruleId)
+        {
+            var activeEvent = await GetActivePenaltyEvent(order.DocEntry);
+            bool isOverdue = info.TotalOverdueAmount > 0 && info.TotalOverdueDays > gracePeriod;
+
+            if (isOverdue)
+            {
+                if (activeEvent == null) await CreateNewPenaltyEvent(order, date, info, ruleId);
+                else if (Math.Abs(activeEvent.PenaltyBaseAmount - info.TotalOverdueAmount) > 0.01M)
+                {
+                    await EndCurrentEvent(activeEvent, date);
+                    await CreateNewPenaltyEvent(order, date, info, ruleId);
+                }
+            }
+            else if (activeEvent != null) await EndCurrentEvent(activeEvent, date);
+        }
