+                    .Select(td => new InvoiceHistoryItem
+                    {
+                        InvoiceDate = td.TaxDate.Value,
+                        InvoiceAmount = td.TaxAmount.Value,
+                        BillId = master.Id,
+                        TaxNo = td.TaxNo
+                    }).OrderBy(item => item.InvoiceDate).ToList();
+                
+                if (!invoiceDict.ContainsKey(master.DocEntry))
+                    invoiceDict[master.DocEntry] = new List<InvoiceHistoryItem>();
+                invoiceDict[master.DocEntry].AddRange(details);
+            }
+            cache.OrderInvoices = invoiceDict;
+
+            // 4. 批量加载收款信息
+            var receiptDict = new Dictionary<int, List<ReceiptForOrder>>();
+
+            // 先加载直接收款的 ORCT（暂存，后续统一计算 AppliedAmount）
+            // 分批查询，避免 SQL IN 子句超过参数上限
+            var directReceiptsByOrder = await LoadDirectReceipts(orderIds);
+
+            // 5. 批量加载间接收款信息（DLN1 → INV1 → RCT2 → ORCT）
+            var indirectReceiptData = await LoadIndirectReceiptData(orderIds);
+            var indirectRct2DocNums = indirectReceiptData.IndirectRct2DocNums;
