+        /// <summary>
+        /// 优化后的单订单处理方法（使用预加载数据）
+        /// </summary>
+        private async Task ProcessSingleOrderByRangeOptimized(ORDR order, DateTime startDate, DateTime endDate, SharedDataCache sharedData)
+        {
+            try
+            {
+                // 1. 删除该订单的现有罚息事件和账本记录（直接查询数据库删除）
+                if (sharedData.OrderPenaltyEvents.TryGetValue(order.DocEntry, out var existingEvents) && existingEvents.Any())
+                {
+                    var eventIds = existingEvents.Select(e => e.Id).ToList();
+
+                    // 先删除罚息账本记录
+                    await UnitWork.DeleteAsync<PenaltyLedger>(pl => eventIds.Contains(pl.EventId));
+
+                    // 再删除罚息事件
+                    await UnitWork.DeleteAsync<PenaltyEvent>(pe => eventIds.Contains(pe.Id));
+
+                    await UnitWork.SaveAsync();
+                }
+
+                // 2. 获取客户类型
+                bool isSchoolOrResearch = false;
+                if (sharedData.CustomerTypes.TryGetValue(order.CardCode, out var customerType))
+                {
+                    isSchoolOrResearch = customerType.CardType.Contains("校") || customerType.CardType.Contains("研");
+                }
+
+                // 3. 获取首次开票日期
+                if (!sharedData.OrderInvoices.TryGetValue(order.DocEntry, out var invoices) || !invoices.Any())
+                    return;
+
+
+                // 4. 获取规则
+                var rule = isSchoolOrResearch ? sharedData.SchoolRule : sharedData.OtherRule;
+                if (rule == null) return;
+
+                var rateTiers = Newtonsoft.Json.JsonConvert.DeserializeObject<List<InterestRateTier>>(rule.Param_String1);
+
+                // 5. 获取因子
+                sharedData.SaleOrderPlugins.TryGetValue(order.DocEntry, out var saleOrderPlugin);
+                decimal factor = (saleOrderPlugin?.NeedReturn == NeedReturnEnums.Select) ? 0.5M : 1.0M;
+
+                // 6. 获取预加载的发票和收款数据
+                if (!sharedData.OrderInvoices.TryGetValue(order.DocEntry, out var orderInvoices))
+                    orderInvoices = new List<InvoiceHistoryItem>();
+
+                if (!sharedData.OrderReceipts.TryGetValue(order.DocEntry, out var orderReceipts))
+                    orderReceipts = new List<ReceiptForOrder>();
+
+                // 转换为 CalculationService 所需的 InvoiceHistoryItem 格式
+                var calculationInvoices = orderInvoices.Select(inv => new HistoricalAfterBillOverdueCalculationService.InvoiceHistoryItem
+                {
+                    InvoiceDate = inv.InvoiceDate,
+                    InvoiceAmount = inv.InvoiceAmount,
+                    BillId = inv.BillId,
+                    TaxNo = inv.TaxNo
+                }).ToList();
+
+                // 7. 获取可清截止日期
+                sharedData.CanClearCutOffDates.TryGetValue(order.DocEntry, out var canClearCutOffDate);
+
+                // 8. 使用内存计算方法计算每日逾期明细
+                var dailyOverdueDetails = _historicalAfterBillOverdueCalculationService.CalculateDailyOverdueDetailsInMemory(
+                    startDate,
+                    endDate,
+                    isSchoolOrResearch,
+                    calculationInvoices,
+                    orderReceipts,
+                    canClearCutOffDate);
+
+                // 9. 根据逾期金额变化动态创建罚息事件和账本记录
+                await CreatePenaltyEventsAndLedgersByOverdueAmountChangesNonScoped(
+                    order,
+                    dailyOverdueDetails,
+                    rule.Id,
+                    factor,
+                    rateTiers,
+                    sharedData.SlpNames);
+            }
+            catch (Exception ex)
+            {
+                LogHelper.Error(ex, $"处理订单{order.DocEntry}的开票后历史逾期数据失败", nameof(HistoricalAfterBillOverdueImportService), nameof(ProcessSingleOrderByRangeOptimized));
+            }
+        }
