+        /// <summary>
+        /// 根据逾期金额变化动态创建罚息事件和账本记录（非Scoped版本，使用this.UnitWork）
+        /// </summary>
+        private async Task CreatePenaltyEventsAndLedgersByOverdueAmountChangesNonScoped(
+            ORDR order,
+            List<HistoricalAfterBillOverdueCalculationService.DailyOverdueDetail> dailyOverdueDetails,
+            int ruleDefinitionId,
+            decimal factor,
+            List<InterestRateTier> rateTiers,
+            Dictionary<int, string> slpNames)
+        {
+            PenaltyEvent currentActiveEvent = null;
+            decimal currentOverdueAmount = 0M;
+            var ledgersToAdd = new List<PenaltyLedger>();
+
+            // 按日期顺序遍历（必须是升序）
+            var sortedDetails = dailyOverdueDetails.OrderBy(d => d.CalculationDate).ToList();
+
+            for (int i = 0; i < sortedDetails.Count; i++)
+            {
+                var dailyDetail = sortedDetails[i];
+
+                // 跳过宽限期内的数据（宽限期内不产生罚息事件）
+                if (dailyDetail.IsInGracePeriod)
+                    continue;
+
+                var nextDayOverdueAmount = dailyDetail.OverdueAmount;
+
+                // 检查逾期金额是否发生变化（只在非宽限期内检查）
+                bool overdueAmountChanged = Math.Abs(nextDayOverdueAmount - currentOverdueAmount) > 0.01M;
+
+                if (overdueAmountChanged)
+                {
+                    // 逾期金额发生变化
+
+                    // 1. 结束当前 ACTIVE 事件（如果存在）
+                    if (currentActiveEvent != null)
+                    {
+                        var resolvedDate = dailyDetail.CalculationDate.AddDays(-1);
+                        currentActiveEvent.ResolvedDate = resolvedDate;
+                        currentActiveEvent.EventStatus = "RESOLVED";
+                        // 在Description后添加结束信息
+                        currentActiveEvent.Description += $" (已结束于{resolvedDate:yyyy.MM.dd})";
+                        await UnitWork.UpdateAsync<PenaltyEvent>(currentActiveEvent);
+                        await UnitWork.SaveAsync();
+
+                        // 批量插入当前事件的账本记录
+                        if (ledgersToAdd.Any())
+                        {
+                            await UnitWork.BatchAddAsync<PenaltyLedger, int>(ledgersToAdd.ToArray());
+                            await UnitWork.SaveAsync();
+                            ledgersToAdd.Clear();
+                        }
+
+                        currentActiveEvent = null;
+                    }
+
+                    // 2. 如果新的逾期金额 > 0，创建新的 ACTIVE 事件
+                    if (nextDayOverdueAmount > 0)
+                    {
+                        currentActiveEvent = new PenaltyEvent
+                        {
+                            RuleDefinitionId = ruleDefinitionId,
+                            SlpCode = order.SlpCode,
+                            TriggerDocType = "ORDR",
+                            SEDocEntry = order.DocEntry,
+                            TriggerDocEntry = order.DocEntry.ToString(),
+                            PenaltyStartDate = dailyDetail.CalculationDate,
+                            ResolvedDate = null,
+                            EventStatus = "ACTIVE",
+                            PenaltyBaseAmount = nextDayOverdueAmount,
+                            TriggerEventDate = dailyDetail.CalculationDate,
+                            Description = $"订单{order.DocEntry}逾期罚息，基础金额：{nextDayOverdueAmount:F6}，开始日期：{dailyDetail.CalculationDate:yyyy.MM.dd}",
+                            Remark = $"导入时间：{DateTime.Now:yyyy-MM-dd HH:mm:ss}"
+                        };
+
+                        await UnitWork.AddAsync<PenaltyEvent, int>(currentActiveEvent);
+                        await UnitWork.SaveAsync();
+                    }
+
+                    // 更新当前逾期金额
+                    currentOverdueAmount = nextDayOverdueAmount;
+                }
+
+                // 3. 为当前 ACTIVE 事件创建罚息账本记录
+                if (currentActiveEvent != null && dailyDetail.OverdueAmount > 0)
+                {
+                    var dailyPenalty =  CalculateDailyPenalty( dailyDetail, factor, rateTiers);
+                    if (dailyPenalty.PenaltyAmount > 0)
+                    {
+                        var ledger = CreatePenaltyLedgerEntryOptimized(
+                            order,
+                            currentActiveEvent,
+                            dailyDetail,
+                            dailyPenalty.PenaltyAmount, dailyPenalty.Rate,
+                            dailyDetail.CalculationDate,
+                            slpNames);
+                        ledgersToAdd.Add(ledger);
+                    }
+                }
+            }
+
+            // 4. 处理最后一个事件
+            if (currentActiveEvent != null)
+            {
+                // 获取非宽限期的最后一天
+                var lastNonGraceDetail = sortedDetails.LastOrDefault(d => !d.IsInGracePeriod);
+                if (lastNonGraceDetail != null && lastNonGraceDetail.OverdueAmount == 0)
+                {
+                    currentActiveEvent.ResolvedDate = lastNonGraceDetail.CalculationDate;
+                    currentActiveEvent.EventStatus = "RESOLVED";
+                    // 在Description后添加结束信息
+                    currentActiveEvent.Description += $" (已结束于{lastNonGraceDetail.CalculationDate:yyyy.MM.dd})";
+                    await UnitWork.UpdateAsync<PenaltyEvent>(currentActiveEvent);
+                    await UnitWork.SaveAsync();
+                }
+
+                // 批量插入最后的账本记录
+                if (ledgersToAdd.Any())
+                {
+                    await UnitWork.BatchAddAsync<PenaltyLedger, int>(ledgersToAdd.ToArray());
+                    await UnitWork.SaveAsync();
+                }
+            }
+        }
