+
+                var parallelOptions = new ParallelOptions
+                {
+                    MaxDegreeOfParallelism = maxDegreeOfParallelism
+                };
+
+                await Task.Run(() =>
+                {
+                    Parallel.ForEach(
+                        orders,
+                        parallelOptions,
+                        (order, state) =>
+                        {
+                            using (var scope = _serviceProvider.CreateScope())
+                            {
+                                try
+                                {
+                                    var scopedUnitWork = scope.ServiceProvider.GetRequiredService<IUnitWork>();
+                                    var scopedCalculationService = scope.ServiceProvider.GetRequiredService<HistoricalAfterBillOverdueCalculationService>();
+
+                                    // 执行单订单重新计算
+                                    RecalculateSingleOrderInternal(
+                                        scopedUnitWork,
+                                        scopedCalculationService,
+                                        order,
+                                        startDate,
+                                        endDate,
+                                        ruleDefinitionIds,
+                                        sharedData).GetAwaiter().GetResult();
+
+                                    lock (lockObj)
+                                    {
+                                        result.SuccessOrders++;
+                                    }
+
+                                    // 定期记录进度
+                                    var now = DateTime.Now;
+                                    if ((now - lastProgressLogTime).TotalSeconds >= progressLogIntervalSeconds)
+                                    {
+                                        lock (lockObj)
+                                        {
+                                            var progress = (result.SuccessOrders * 100.0 / result.TotalOrders);
+                                            var elapsedSeconds = stopwatch.Elapsed.TotalSeconds;
+                                            var throughput = result.SuccessOrders / elapsedSeconds;
+                                            var estimatedRemaining = (result.TotalOrders - result.SuccessOrders) / throughput;
+
+                                            Console.Write($"\r进度：[");
+                                            var barLength = 50;
+                                            var filled = (int)(progress / 100 * barLength);
+                                            Console.Write(new string('█', filled));
+                                            Console.Write(new string('░', barLength - filled));
+                                            Console.Write($"] {result.SuccessOrders}/{result.TotalOrders} ({progress:F2}%) | ");
+                                            Console.Write($"耗时：{elapsedSeconds:F1}秒 | ");
+                                            Console.Write($"速度：{throughput:F2}订单/秒 | ");
+                                            Console.Write($"预计剩余：{estimatedRemaining:F1}秒    ");
+
+                                            LogHelper.Info($"[并行重算] 进度：{result.SuccessOrders}/{result.TotalOrders} ({progress:F2}%)，耗时：{elapsedSeconds:F1}秒，吞吐量：{throughput:F2}订单/秒，预计剩余：{estimatedRemaining:F1}秒",
+                                                nameof(HistoricalAfterBillOverdueImportService), nameof(RecalculateHistoricalAfterBillOverdueParallel));
+
+                                            lastProgressLogTime = now;
+                                        }
+                                    }
+                                }
+                                catch (Exception ex)
+                                {
+                                    lock (lockObj)
+                                    {
+                                        result.FailedOrders++;
+                                        result.Errors.Add($"订单 {order.DocEntry}: {ex.Message}");
+                                    }
+                                    LogHelper.Error(ex, $"重新计算订单 {order.DocEntry} 失败",
+                                        nameof(HistoricalAfterBillOverdueImportService), nameof(RecalculateHistoricalAfterBillOverdueParallel));
+                                }
+                            }
+                        });
+                });
+
+                stopwatch.Stop();
+                result.EndTime = DateTime.Now;
+                result.TotalSeconds = stopwatch.Elapsed.TotalSeconds;
+
+                // 输出最终进度条
+                Console.WriteLine();
+                Console.WriteLine($"✓ 重新计算完成！");
+                Console.WriteLine($"成功：{result.SuccessOrders}，失败：{result.FailedOrders}，总耗时：{result.TotalSeconds:F2}秒");
+
+                LogHelper.Info($"重新计算完成：成功 {result.SuccessOrders}，失败 {result.FailedOrders}，总耗时：{result.TotalSeconds:F2}秒",
+                    nameof(HistoricalAfterBillOverdueImportService), nameof(RecalculateHistoricalAfterBillOverdueParallel));
+            }
+            catch (Exception ex)
+            {
+                result.EndTime = DateTime.Now;
+                LogHelper.Error(ex, "重新计算历史开票逾期罚息失败",
+                    nameof(HistoricalAfterBillOverdueImportService), nameof(RecalculateHistoricalAfterBillOverdueParallel));
+                throw;
+            }
+
+            return result;
+        }
