+        /// <summary>
+        /// 重新计算单个订单（内部方法，用于并行调用）
+        /// </summary>
+        private async Task RecalculateSingleOrderInternal(
+            IUnitWork scopedUnitWork,
+            HistoricalAfterBillOverdueCalculationService scopedCalculationService,
+            ORDR order,
+            DateTime startDate,
+            DateTime endDate,
+            List<int> ruleDefinitionIds,
+            SharedDataCache sharedData)
+        {
+            try
+            {
+                // 1. 查询该订单的所有罚息事件并删除
+                var existingEvents = await scopedUnitWork.Find<PenaltyEvent>(pe =>
+                        pe.SEDocEntry == order.DocEntry &&
+                        pe.TriggerDocType == "ORDR" &&
+                        ruleDefinitionIds.Contains(pe.RuleDefinitionId))
+                    .ToListAsync();
+
+                if (existingEvents.Any())
+                {
+                    var eventIds = existingEvents.Select(e => e.Id).ToList();
+
+                    // 2. 先删除罚息账本记录（因为有外键约束）
+                    var existingLedgers = await scopedUnitWork.Find<PenaltyLedger>(pl => eventIds.Contains(pl.EventId)).ToListAsync();
+                    if (existingLedgers.Any())
+                    {
+                        foreach (var ledger in existingLedgers)
+                        {
+                            await scopedUnitWork.DeleteAsync<PenaltyLedger>(ledger);
+                        }
+                        await scopedUnitWork.SaveAsync();
+                    }
+
+                    // 3. 再删除罚息事件
+                    foreach (var evt in existingEvents)
+                    {
+                        await scopedUnitWork.DeleteAsync<PenaltyEvent>(evt);
+                    }
+                    await scopedUnitWork.SaveAsync();
+                }
+
+                // 4. 获取客户类型
+                bool isSchoolOrResearch = false;
+                if (sharedData.CustomerTypes.TryGetValue(order.CardCode, out var customerType))
+                {
+                    isSchoolOrResearch = customerType.CardType.Contains("校") || customerType.CardType.Contains("研");
+                }
+
+                // 5. 获取首次开票日期
+                if (!sharedData.OrderInvoices.TryGetValue(order.DocEntry, out var invoices) || !invoices.Any())
+                    return;
+
+
+                // 6. 获取规则
+                var rule = isSchoolOrResearch ? sharedData.SchoolRule : sharedData.OtherRule;
+                if (rule == null) return;
+
+                var rateTiers = Newtonsoft.Json.JsonConvert.DeserializeObject<List<InterestRateTier>>(rule.Param_String1);
+
+                // 7. 获取因子
+                sharedData.SaleOrderPlugins.TryGetValue(order.DocEntry, out var saleOrderPlugin);
+                decimal factor = (saleOrderPlugin?.NeedReturn == NeedReturnEnums.Select) ? 0.5M : 1.0M;
+
+                // 8. 获取预加载的发票和收款数据
+                if (!sharedData.OrderInvoices.TryGetValue(order.DocEntry, out var orderInvoices))
+                    orderInvoices = new List<InvoiceHistoryItem>();
+
+                if (!sharedData.OrderReceipts.TryGetValue(order.DocEntry, out var orderReceipts))
+                    orderReceipts = new List<ReceiptForOrder>();
+
+                // 转换为计算服务所需格式
+                var calculationInvoices = orderInvoices.Select(inv => new HistoricalAfterBillOverdueCalculationService.InvoiceHistoryItem
+                {
+                    InvoiceDate = inv.InvoiceDate,
+                    InvoiceAmount = inv.InvoiceAmount,
+                    BillId = inv.BillId,
+                    TaxNo = inv.TaxNo
+                }).ToList();
+
+                // 获取可清截止日期
+                sharedData.CanClearCutOffDates.TryGetValue(order.DocEntry, out var canClearCutOffDate);
+
+                // 9. 使用内存计算方法计算每日逾期明细
+                var dailyOverdueDetails = scopedCalculationService.CalculateDailyOverdueDetailsInMemory(
+                    startDate,
+                    endDate,
+                    isSchoolOrResearch,
+                    calculationInvoices,
+                    orderReceipts,
+                    canClearCutOffDate);
+
+                // 10. 根据逾期金额变化动态创建罚息事件和账本记录
+                await CreatePenaltyEventsAndLedgersByOverdueAmountChanges(
+                    scopedUnitWork,
+                    order,
+                    dailyOverdueDetails,
+                    rule.Id,
+                    factor,
+                    rateTiers,
+                    sharedData.SlpNames);
+            }
+            catch (Exception ex)
+            {
+                LogHelper.Error(ex, $"重新计算订单 {order.DocEntry} 失败",
+                    nameof(HistoricalAfterBillOverdueImportService), nameof(RecalculateSingleOrderInternal));
+                throw;
+            }
+        }
+
+        /// <summary>
+        /// 根据逾期金额变化动态创建罚息事件和账本记录
+        /// </summary>
+        /// <remarks>
+        /// 核心逻辑：
+        /// 1. 当逾期金额发生变化时，结束当前ACTIVE事件，创建新的ACTIVE事件
+        /// 2. 当逾期金额变为0时，结束当前ACTIVE事件（收款达到开票金额）
+        /// 3. PenaltyBaseAmount = 当前逾期金额
+        /// </remarks>
+        private async Task CreatePenaltyEventsAndLedgersByOverdueAmountChanges(
+            IUnitWork scopedUnitWork,
+            ORDR order,
+            List<HistoricalAfterBillOverdueCalculationService.DailyOverdueDetail> dailyOverdueDetails,
+            int ruleDefinitionId,
+            decimal factor,
+            List<InterestRateTier> rateTiers,
+            Dictionary<int, string> slpNames)
+        {
+            PenaltyEvent currentActiveEvent = null;
+            decimal currentOverdueAmount = 0M;
+            var ledgersToAdd = new List<PenaltyLedger>();
+
+            // 按日期顺序遍历（必须是升序）
+            var sortedDetails = dailyOverdueDetails.OrderBy(d => d.CalculationDate).ToList();
+
+            for (int i = 0; i < sortedDetails.Count; i++)
+            {
+                var dailyDetail = sortedDetails[i];
+
+                // 跳过宽限期内的数据（宽限期内不产生罚息事件）
+                if (dailyDetail.IsInGracePeriod)
+                    continue;
+
+                var nextDayOverdueAmount = dailyDetail.OverdueAmount;
+
+                // 检查逾期金额是否发生变化（只在非宽限期内检查）
+                bool overdueAmountChanged = Math.Abs(nextDayOverdueAmount - currentOverdueAmount) > 0.01M;
+
+                if (overdueAmountChanged)
+                {
+                    // 逾期金额发生变化
+
+                    // 1. 结束当前 ACTIVE 事件（如果存在）
+                    if (currentActiveEvent != null)
+                    {
+                        var resolvedDate = dailyDetail.CalculationDate.AddDays(-1); // 结束日期为变化前一天
+                        currentActiveEvent.ResolvedDate = resolvedDate;
+                        currentActiveEvent.EventStatus = "RESOLVED";
+                        // 在Description后添加结束信息
+                        currentActiveEvent.Description += $" (已结束于{resolvedDate:yyyy.MM.dd})";
+                        await scopedUnitWork.UpdateAsync<PenaltyEvent>(currentActiveEvent);
+                        await scopedUnitWork.SaveAsync();
+
+                        // 批量插入当前事件的账本记录
+                        if (ledgersToAdd.Any())
+                        {
+                            await scopedUnitWork.BatchAddAsync<PenaltyLedger, int>(ledgersToAdd.ToArray());
+                            await scopedUnitWork.SaveAsync();
+                            ledgersToAdd.Clear();
+                        }
+
+                        currentActiveEvent = null;
+                    }
+
+                    // 2. 如果新的逾期金额 > 0，创建新的 ACTIVE 事件
+                    if (nextDayOverdueAmount > 0)
+                    {
+                        currentActiveEvent = new PenaltyEvent
+                        {
+                            RuleDefinitionId = ruleDefinitionId,
+                            SlpCode = order.SlpCode,
+                            TriggerDocType = "ORDR",
+                            SEDocEntry = order.DocEntry,
+                            TriggerDocEntry = order.DocEntry.ToString(),
+                            PenaltyStartDate = dailyDetail.CalculationDate,
+                            ResolvedDate = null, // ACTIVE 事件的结束日期为 null
+                            EventStatus = "ACTIVE",
+                            PenaltyBaseAmount = nextDayOverdueAmount,
+                            TriggerEventDate = dailyDetail.CalculationDate,
+                            Description = $"订单{order.DocEntry}开票逾期罚息，基础金额：{nextDayOverdueAmount:F6}，开始日期：{dailyDetail.CalculationDate:yyyy.MM.dd}",
+                            Remark = $"重算时间：{DateTime.Now:yyyy-MM-dd HH:mm:ss}"
+                        };
+
+                        await scopedUnitWork.AddAsync<PenaltyEvent, int>(currentActiveEvent);
+                        await scopedUnitWork.SaveAsync();
+                    }
+
+                    // 更新当前逾期金额
+                    currentOverdueAmount = nextDayOverdueAmount;
+                }
+
+                // 3. 为当前 ACTIVE 事件创建罚息账本记录
+                if (currentActiveEvent != null && dailyDetail.OverdueAmount > 0)
+                {
+                    var dailyPenalty = CalculateDailyPenalty(dailyDetail, factor, rateTiers);
+                    if (dailyPenalty.PenaltyAmount > 0)
+                    {
+                        var ledger = CreatePenaltyLedgerEntryOptimized(order, currentActiveEvent, dailyDetail, dailyPenalty.PenaltyAmount, dailyPenalty.Rate, dailyDetail.CalculationDate, slpNames);
+                        ledgersToAdd.Add(ledger);
+                    }
+                }
+            }
+
+            // 4. 处理最后一个事件
+            if (currentActiveEvent != null)
+            {
+                // 获取非宽限期的最后一天
+                var lastNonGraceDetail = sortedDetails.LastOrDefault(d => !d.IsInGracePeriod);
+                if (lastNonGraceDetail != null && lastNonGraceDetail.OverdueAmount == 0)
+                {
+                    // 只有当逾期金额归0时才结束事件
+                    currentActiveEvent.ResolvedDate = lastNonGraceDetail.CalculationDate;
+                    currentActiveEvent.EventStatus = "RESOLVED";
+                    // 在Description后添加结束信息
+                    currentActiveEvent.Description += $" (已结束于{lastNonGraceDetail.CalculationDate:yyyy.MM.dd})";
+                    await scopedUnitWork.UpdateAsync<PenaltyEvent>(currentActiveEvent);
+                    await scopedUnitWork.SaveAsync();
+                    // 否则保持ACTIVE状态，不设置ResolvedDate
+                }
+
+                // 批量插入最后的账本记录
+                if (ledgersToAdd.Any())
+                {
+                    await scopedUnitWork.BatchAddAsync<PenaltyLedger, int>(ledgersToAdd.ToArray());
+                    await scopedUnitWork.SaveAsync();
+                }
+            }
+        }
